function addMonths(y,m,d,months) {
  let y2=y, m2=m-1+months;
  y2 += Math.floor(m2/12);
  m2 = (m2 % 12) + 1;
  // clamp day for month length
  const daysInMonth = new Date(y2, m2, 0).getDate();
  const d2 = Math.min(d, daysInMonth);
  return y2+'-'+String(m2).padStart(2,'0')+'-'+String(d2).padStart(2,'0');
}
console.log('180 payments (last = first + 179 mo):', addMonths(2013,4,7,179));
console.log('first + 180 mo:', addMonths(2013,4,7,180));
